                ["Netto-Stueckpreise werden wie in PowerBI als Minimum je Artikel und Jahr gezeigt."] = "Çmimet neto për njësi tregohen si në Power BI si minimum sipas artikullit dhe vitit.",
                ["Lieferantenspend wird als Pareto ausgewertet, um Abhaengigkeit und Buendelungspotenzial zu zeigen."] = "Shpenzimet e furnizuesit vlerësohen si pareto për të treguar varësinë dhe potencialin e paketimit.",
                ["Pflichtfelder und Nullwerte im Einkauf-Cache werden als Qualitaetsampel gezaehlt."] = "Fushat e kërkuara dhe vlerat zero në cache-in e blerjeve llogariten si tregues të cilësisë.",
                ["Echte Analyse aus dem Einkauf-Cache."] = "Analiza reale nga cache e blerjes.",
                ["Offener Wert nach Faelligkeit"] = "Vlera e hapur sipas datës së caktuar",
                ["Min. Stueckpreis nach Jahr"] = "Min. çmimi për njësi sipas vitit",
                ["Top Lieferanten Spend"] = "Shpenzimet kryesore të furnizuesit",
                ["Datenqualitaetsfehler"] = "Probleme me cilësinë e të dhënave",
                ["Beschaffungsregion"] = "Rajoni i prokurimit",
                ["Waehrung"] = "Monedha",
                ["Material"] = "Materiali",
                ["Waehrung des Bestellbelegs (EKKO-Waers). Balken und erster Betrag sind nach CHF bewertet, damit die Waehrungen vergleichbar sind; in Klammern die Summe in der Belegwaehrung selbst (das tatsaechliche Waehrungsexposure). NICHT die Beschaffungsregion: ein Schweizer Lieferant kann in EUR fakturieren."] = "Monedha e porosisë së blerjes (EKKO Waers). Shufrat dhe shuma e parë vlerësohen në CHF, kështu që monedhat janë të krahasueshme; në kllapa shuma në vetë monedhën e dokumentit (ekspozimi aktual i monedhës). JO rajoni i prokurimit: një furnizues zviceran mund të faturojë në EUR.",
                ["Beschaffungsregion = Land des Lieferanten (LFA1-Land1), ueber den Bestellbeleg zugeordnet. Zeigt den CHF-Spend je Lieferantenland im gewaehlten Zeitraum."] = "Rajoni i prokurimit = vendi furnizues (LFA1 Toka1), i caktuar nëpërmjet urdhër blerjes. Tregon shpenzimet CHF sipas vendit furnizues në periudhën e zgjedhur.",
                ["Warengruppe aus dem Materialstamm (MARA-MATKL), Fallback Beleg-Warengruppe (EKPO.Matkl). Texte aus dem SAP-Export T023T; unbekannte Codes zeigen den reinen Code. \"01\" ist die SAP-Sammelgruppe \"Dummy\" fuer unklassifizierte Altbestaende."] = "Grupi i materialeve nga masteri i materialit (MARA-MATKL), kthim në grupin e materialeve të dokumenteve (EKPO.Matkl). Tekste nga eksporti SAP T023T; kodet e panjohura tregojnë kodin e zhveshur. \"01\" është grupi \"Dummy\" i SAP-it për stokun e vjetër të paklasifikuar.",
                ["Zuordnung: Einkaufsmaterial -> ZLO03-Komponente -> Disponent des verwendenden Kopfmaterials -> ZC23-Produktgruppe. Wird eine Komponente in mehreren unterschiedlichen Produktgruppen verwendet, wird ihr Spend gleichmaessig 1/n verteilt. Dadurch bleibt die Summe exakt erhalten. Fehlende ZC23-Texte erscheinen ehrlich als 'Disponent <Code>'."] = "Caktimi: material blerjeje -> komponent ZLO03 -> planifikuesi i materialit kryesor -> grupi i produktit ZC23. Kur nje komponent perdoret nga disa grupe, shpenzimi ndahet ne menyre te barabarte 1/n. Totali ruhet saktesisht. Tekstet ZC23 qe mungojne shfaqen si 'Planifikues <kod>'.",
                ["Zuordnung: Einkaufsmaterial -> ZLO03-Komponente -> Disponent des verwendenden Kopfmaterials -> Produktname. Bestehende manuelle Zuordnungen bleiben fuehrend; nur wenn dort kein Name steht, ergaenzen zdispo_grp.xlsx und zdispo_spart.xlsx den Namen. Bei mehreren Produktgruppen wird der Spend gleichmaessig 1/n verteilt und die Summe bleibt erhalten. Ohne Treffer erscheint 'Disponent <Code>'."] = "Caktimi: material blerjeje -> komponent ZLO03 -> planifikuesi i materialit kryesor -> emri i produktit. Caktimet manuale ekzistuese mbeten paresore; zdispo_grp.xlsx dhe zdispo_spart.xlsx e plotesojne emrin vetem kur mungon. Per disa grupe shpenzimi ndahet ne menyre te barabarte 1/n dhe totali ruhet. Pa perputhje shfaqet 'Planifikues <kod>'.",
                ["Ohne Produktgruppe"] = "Pa grup produkti",
                ["Mehrfachverwendung"] = "Perdorim i shumefishte",
                ["ABC/XYZ-Massnahmenmatrix"] = "Matrica e veprimeve ABC/XYZ",
                ["ABC priorisiert die Wertbedeutung, XYZ die Regelmaessigkeit des Bedarfs. Die Kombination uebersetzt den Spend in einen konkreten Pruefauftrag; sie aendert keine Disposition automatisch."] = "ABC i jep perparesi rendesise se vleres dhe XYZ rregullsise se kerkeses. Kombinimi e kthen shpenzimin ne nje kontroll konkret; planifikimi nuk ndryshon automatikisht.",
                ["Keine ABC/XYZ-Daten im gewaehlten Zeitraum."] = "Nuk ka te dhena ABC/XYZ ne periudhen e zgjedhur.",
                ["Klasse"] = "Klasa",
                ["Empfohlener Pruefauftrag"] = "Kontrolli i rekomanduar",
                ["mittel"] = "mesatare",
                ["high"] = "e larte",
                ["medium"] = "mesatare",
                ["Stammdaten nachpflegen; ohne beide Klassen ist keine belastbare Beschaffungsstrategie ableitbar."] = "Plotesoni te dhenat baze; pa te dyja klasat nuk mund te nxirret nje strategji e besueshme blerjeje.",
                ["Strategisch absichern: Rahmenvertrag, Lieferfaehigkeit und automatische Disposition pruefen."] = "Siguroni strategjikisht: kontrolloni kontraten kuader, aftesine e furnizimit dhe planifikimin automatik.",
                ["Versorgungsrisiko priorisieren: Forecast, Sicherheitsbestand und Zweitquelle pruefen."] = "Jepini perparesi rrezikut te furnizimit: kontrolloni parashikimin, stokun e sigurise dhe burimin e dyte.",
                ["Standardisieren und Mengen buendeln; Bestellrhythmus und Konditionen optimieren."] = "Standardizoni dhe bashkoni sasite; optimizoni ritmin e porosive dhe kushtet.",
                ["Losgroessen, Mindestmengen und schwankende Bedarfsursachen mit dem Disponenten pruefen."] = "Kontrolloni me planifikuesin madhesite e serive, sasite minimale dhe shkaqet e kerkeses se paqendrueshme.",
                ["Prozesskosten senken: Katalog, Automatisierung und Sammelbestellungen pruefen."] = "Ulni kostot e procesit: kontrolloni katalogun, automatizimin dhe porosite e bashkuara.",
                ["Tail Spend reduzieren: buendeln, auslisten oder auf Standardalternativen umstellen."] = "Ulni shpenzimet e vogla: bashkoni, hiqni ose kaloni ne alternativa standarde.",
                ["Klassifikation fachlich pruefen und anschliessend einer Beschaffungsstrategie zuordnen."] = "Verifikoni klasifikimin dhe caktojeni me pas ne nje strategji blerjeje.",
